// WoW Forever talent trees. Bundled data is generated by `npm run talents`; the desktop app can also
// download newer beta data at runtime (see electron/main.cjs), which takes priority when present.
// Talent: { name, row, col, max, ranks: [description per rank], req?, reqQty? }
import FOREVER from './forever.json' with { type: 'json' };
import ABILITIES from './abilities.json' with { type: 'json' };

const override = (() => {
  try {
    const data = globalThis.everhart?.getTalentOverride?.();
    return data?.classes && data?.meta ? data : null;
  } catch {
    return null;
  }
})();

const ACTIVE = override ?? FOREVER;

/** Where the talent data came from: bundled with the app, or downloaded by the in-app updater. */
export const TALENT_META = { ...ACTIVE.meta, origin: override ? 'downloaded' : 'bundled', bundled: FOREVER.meta };
/** Talent icon names from downloaded data (empty when using bundled data). */
export const OVERRIDE_ICONS = override?.icons ?? {};

const TREE_COLORS = {
  'warrior/arms': '#b8743a', 'warrior/fury': '#c0392b', 'warrior/protection': '#5b7fa6',
  'paladin/holy': '#e3c25a', 'paladin/protection': '#5b84b3', 'paladin/retribution': '#c4413c',
  'hunter/beast-mastery': '#b55a3a', 'hunter/marksmanship': '#4c86b5', 'hunter/survival': '#7e9a3c',
  'rogue/assassination': '#4c9a52', 'rogue/combat': '#b0453a', 'rogue/subtlety': '#6d5a9c',
  'priest/discipline': '#c8b46a', 'priest/holy': '#e6d9a8', 'priest/shadow': '#7a4aa8',
  'shaman/elemental': '#3d7bd6', 'shaman/enhancement': '#a35a2e', 'shaman/restoration': '#3fa58a',
  'mage/arcane': '#9a6ad1', 'mage/fire': '#d8572a', 'mage/frost': '#4a9fd6',
  'warlock/affliction': '#6a9a3a', 'warlock/demonology': '#8b4bb8', 'warlock/destruction': '#d4542a',
  'druid/balance': '#4f7fc4', 'druid/feral': '#c25a2a', 'druid/restoration': '#4ea852',
};

/** The three Forever talent trees for a class, with display colors. */
export function foreverTrees(classId) {
  return ACTIVE.classes[classId].map((tree) => ({ ...tree, color: TREE_COLORS[`${classId}/${tree.id}`] }));
}

/** [abilityName, levelLearned] pairs for a class, sorted by level. */
export const classAbilities = (classId) => (override?.abilities ?? ABILITIES)[classId] ?? [];
